WITH ins15_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 15, 0, $h15$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل الثانى - إدارة الشركة - ثانيًا : مجلس إدارة الشركة$h15$, $t15_0$المادة 15 - مهام ومسئوليات العضو المنتدب/الرئيس التنفيذي$t15_0$, $b15_0$يجب أن تتضمن لائحة الحوكمة الخاصة بالشركة تحديد مهام ومسئوليات العضو المنتدب/ الرئيس التنفيذى وكذا مهام ومسئوليات مساعديه حال وجودهم .
وتشمل مهام ومسئوليات العضو المنتدب/ الرئيس التنفيذى بحد أدنى ما يلى :
1- تنفيذ استراتيجية وخطة العمل السنوية للشركة ، وكافة السياسات واللوائح والنظم الداخلية للشركة المعتمدة من مجلس الإدارة .
2- رئاسة العمل التنفيذى بالشركة والإشراف على سير العمل اليومى فى جميع أنشطتها واتخاذ القرارات اللازمة بما يحقق انتظام العمل بها وتحقيق أهدافها .
3- تهيئة بيئة عمل مناسبة تمكن المسئولين الرئيسيين عن الأنشطة أو الإدارات الآتية : المراجعة الداخلية ، والالتزام ، والمخاطر ، ومكافحة غسل الأموال وتمويل الإرهاب من أداء مهامها باستقلال تام ، ودون أى تدخل فى أعمالها .
4- اقتراح الموضوعات التى تعرض فى اجتماعات مجلس الإدارة ، بالتنسيق مع رئيس المجلس .
5- الإشراف على إعداد ومراجعة التقارير الدورية المتعلقة بنتائج أعمال الشركة وتقييم أدائها ، ومراجعة التقرير السنوى للحوكمة ، وكافة الردود على استفسارات مراقبى الحسابات قبل إعداد هذه التقارير .
6- الإشراف على تطبيق قواعد السلوك المهنى داخل الشركة ، واقتراح نظم الإثابة والتحفيز وخطة التعاقب الوظيفى بما يعزز ولاء العاملين ويسهم فى تعظيم قيمة الشركة .
7- تحديد مهام ومسئوليات كافة العاملين بالشركة ، وفقًا للوائح العمل بالشركة وقرارات مجلس الإدارة .$b15_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
