WITH ins16_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 16, 0, $h16$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل الثانى - إدارة الشركة - ثانيًا : مجلس إدارة الشركة$h16$, $t16_0$المادة 16 - اجتماعات مجلس الإدارة$t16_0$, $b16_0$ينعقد مجلس إدارة الشركة بناءً على دعوة من رئيسه أو نائبه ، ويجوز للعضو المنتدب/ الرئيس التنفيذى أو ثلث أعضاء المجلس التقدم كتابة لرئيس المجلس بطلب دعوة مجلس الإدارة للانعقاد على أن يتضمن الطلب تحديد موعد ومكان الاجتماع وجدول الأعمال ، وعلى رئيس المجلس الالتزام بدعوة المجلس وذلك قبل ثلاثة أيام عمل على الأقل عن الموعد المحدد للاجتماع ، وفى حال تخلف رئيس المجلس عن دعوة المجلس فلطالبى الاجتماع القيام بدعوة كافة أعضاء مجلس الإدارة مباشرة وإخطار الهيئة بذلك قبل ثلاثة أيام عمل على الأقل من الموعد المحدد للاجتماع وذلك وفقًا للقواعد والإجراءات المعمول بها فى هذا الشأن بالشركة .
ويتعين عند توجيه الدعوة لاجتماعات المجلس مراعاة تحديد موعد ومكان الانعقاد بما يتناسب مع ظروف الأعضاء ويتيح الحضور الفعلى ، ودون الإخلال بالنظام الأساسى للشركة .
وعلى مجلس الإدارة الاجتماع ست مرات سنويًا على الأقل ، ويتم الإفصاح فى التقرير السنوى للشركة عن عدد اجتماعات مجلس الإدارة المنعقدة وأسماء الأعضاء الذين تغيبوا عن حضور اجتماعات المجلس أو لجانه .
وفى جميع الأحوال ، لا يجوز لأى عضو أن يتغيب عن اجتماعات مجلس إدارة الشركة لأكثر من ثلث عدد جلساته خلال السنة ، وإذا تجاوز تغيب أى عضو ثلث اجتماعات المجلس فيتعين على رئيس المجلس إخطار الجمعية العامة بذلك لاتخاذ ما تراه مناسبًا فى شأن استمرار عضويته بالمجلس .
وتتخذ قرارات مجلس الإدارة بأغلبية أصوات الأعضاء الحاضرين ، وفى الحالات العاجلة التى لا تحتمل التأجيل يجوز اتخاذ القرارات بطريق التمرير شريطة قيام أمانة سر المجلس بإرفاق كافة المستندات والبيانات المتعلقة بالموضوعات المعروضة بالتمرير ، وموافقة جميع أعضاء مجلس الإدارة على القرارات كتابة ، على أن يتم إثبات تلك القرارات فى محضر أول اجتماع لاحق لمجلس الإدارة .
ولمجلس الإدارة الاستعانة بمن يراه ضروريًا لحضور اجتماعاته دون أن يكون له صوت معدود عند التصويت .
ويجوز لمجلس الإدارة عقد اجتماعاته باستخدام وسائل الاتصال الحديثة أو أى وسيلة إلكترونية أخرى شريطة أن ينص النظام الأساسى للشركة على ذلك ، وألا يزيد عدد الاجتماعات المنعقدة بتلك الوسائل عن ثلث عدد اجتماعات المجلس خلال السنة وألا يقل عدد الحضور الفعلى عن نصف أعضاء المجلس ، على أن يكون من بينهم العضو المنتدب/الرئيس التنفيذى ، ويحدد مجلس إدارة الشركة ضوابط وإجراءات عقد الاجتماعات باستخدام تلك الوسائل .
وتعتبر مشاركة عضو مجلس الإدارة عبر هذه الوسائل مشاركة فعلية فى الاجتماع ، ويحسب ضمن النصاب القانونى لصحة الانعقاد والتصويت .$b16_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-10-22', 'active' FROM ins16_0;

