WITH ins19_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 19, 0, $h19$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل الثانى - إدارة الشركة - ثانيًا : مجلس إدارة الشركة$h19$, $t19_0$المادة 19 - المكافآت والبدلات والمزايا الخاصة بمجلس الإدارة$t19_0$, $b19_0$تحدد الجمعية العامة بدلات الحضور والمزايا الأخرى المقررة لأعضاء المجلس ، ويجوز للجمعية العامة أن تقرر صرف مكافأة شهرية لرئيس مجلس إدارة الشركة تحت حساب المكافأة السنوية . ويحدد مجلس الإدارة مكافآت ومرتبات وبدلات العضو المنتدب للشركة ، ويجب على الشركة إتاحة تفاصيل المكافآت والبدلات والمزايا الأخرى المقترحة لجميع المساهمين قبل انعقاد الجمعية العامة التى يتم فيها التصويت على تلك القرارات .
ولا يجوز للشركة منح قروض أو تمويلات لأى من أعضاء مجلس إدارتها إلا بعد موافقة مسبقة من الجمعية العامة مع استبعاد صاحب المصلحة ومجموعته المرتبطة عند التصويت على تلك القرارات ، وذلك بخلاف التمويلات المرتبطة بوثائق التأمين على الحياة ووفقًا لشروط وأحكام تلك الوثائق .
ولا يجوز لعضو مجلس الإدارة أو الإدارة العليا أو موظفى الشركة بما يشمل المسئول التنفيذى عن قنوات التوزيع والمبيعات (باستثناء مديرى المبيعات أو موظفى الجهاز الإنتاجى المقيدين كوسطاء تأمين) الحصول على عمولات أو مكافآت أو مزايا أو منافع نظير الأعمال التى يساهمون فى ابرامها لصالح الشركة ، كما لا يجوز ربط أى جزء من المكافآت والمزايا الخاصة بالعضو أو الإدارة العليا أو أى من موظفى الشركة (باستثناء مديرى المبيعات أو موظفى الجهاز الإنتاجى المقيدين كوسطاء تأمين) بحجم أعمال الشركة بشكل مباشر وبما لا يخل بسلطة مجلس الإدارة أو الجمعية العامة فى تقرير صرف أية مكافآت أو مزايا لعضو مجلس الإدارة أو الإدارة العليا أو موظفى الشركة من الأرباح المحققة سنويًا للشركة$b19_0$
