WITH ins21_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 21, 0, $h21$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل الثالث - أمين سر مجلس الإدارة ومراقب حسابات الشركة$h21$, $t21_0$المادة 21 - مراقب حسابات الشركة$t21_0$, $b21_0$يكون تعيين مراقب حسابات أو أكثر للشركة وتحديد أتعابه بقرار من الجمعية العامة بناءً على ترشيح مجلس الإدارة وفى ضوء توصية لجنة المراجعة الداخلية ، مع الالتزام بما يلى :
1- أن يكون مراقب الحسابات من بين المقيدين بالسجل المعد لذلك بالهيئة ووفقًا للقرارات الصادرة عن الهيئة فى هذا الشأن .
2- ألا يربط مراقب الحسابات ومن يعمل معه علاقة عمل مهنية تؤدى إلى نشوء أى من حالات تعارض المصالح مع الشركات التى يقومون بمراجعة حساباتها ، وأن يكون مستقلاً عن الشركة والشركة الأم وأعضاء مجلس إدارتهما ، ويجب ألا يكون مساهمًا بأى من تلك الشركات أو عضوًا بمجلس إدارتهما أو تربطه صلة قرابة حتى الدرجة الثانية بأى من أعضاء المجلس أو الإدارة التنفيذية العليا ، أو أن يؤدى بصفة دائمة أى أعمال فنية أو إدارية أو استشارية بأى منها ، وأن يكون محايدًا فيما يبديه من أراء ، وألا يخضع عمله لتدخل من مجلس إدارة الشركة .
ويجوز للجمعية العامة التعاقد مع مراقب حسابات الشركة لأداء أعمال إضافية غير مرتبطة مباشرة بمهامه كمراقب للحسابات شريطة ألا تكون تلك الأعمال من الأعمال التى تتعارض مع طبيعة عمله كمراقب حسابات ، وأن تتناسب الأتعاب مع طبيعة وحجم الأعمال الإضافية ، مع الإفصاح عن تلك الأعمال فى التقرير السنوى عن نشاط الشركة وبما لا يخالف معايير المراجعة المصرية .
وفى جميع الأحوال ، يكون تعيين مراقب حسابات الشركة بصورة سنوية ، ويجوز أن يجدد له بحد أقصى ست سنوات مالية متصلة ، ولا يجوز أن يعاد تعيينه إلا بعد مرور ثلاث سنوات مالية من انتهاء الست سنوات المشار إليها .$b21_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-10-22', 'active' FROM ins21_0;

WITH ins22_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 22, 0, $h22$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل الرابع - اللجان المشكلة من مجلس إدارة الشركة$h22$, $t22_0$المادة 22 - اللجان الواجب تشكيلها بالشركة$t22_0$, $b22_0$يلتزم مجلس الإدارة بتشكيل لجان لدعمه فى القيام بالدور المنوط به وتحسين فعالية وكفاءة واستقلالية اتخاذ القرارات داخل المجلس ، وتعزيز الرقابة والحوكمة بالشركة على نحو يتناسب مع حجم أعمالها وطبيعة نشاطها ومستوى المخاطر التى تواجهها ، على النحو الآتى :
1- لجنة الترشيحات والمكافآت .
2- لجنة المراجعة الداخلية .
3- لجنة المخاطر .
4- لجنة الاستثمار .
5- لجنة الحوكمة .
6- لجنة حماية حقوق حملة الوثائق .
وفى جميع الأحوال ، لا يجوز دمج أى من تلك اللجان ، كما لا يجوز تماثل كامل تشكيل أى منها .
كما يتعين على المجلس تشكيل اللجان الآتية :
1- لجنة تكنولوجيا المعلومات والتحول الرقمي
2- لجنة تطوير المنتجات التأمينية .
3- لجنة إدارة الأصول والالتزامات .
4- لجنة الممارسات البيئية والمجتمعية والحوكمة المتعلقة بالاستدامة والحوكمة المناخية .
ويجب أن يكون لكل لجنة من اللجان المشكلة من مجلس الإدارة ميثاق تنظيمى وفق الضوابط الواردة بهذا القرار يعتمد من مجلس إدارة الشركة يتضمن تحديد اختصاصاتها ومسئولياتها وبحد أدنى ما يلى :
1- آليات تشكيل اللجنة ، واختصاصاتها ، ومسئولياتها ، ونطاق ومدة عملها .
2- النصاب القانونى لصحة انعقاد اجتماعاتها .
3- عدد الاجتماعات التى يجب أن تعقدها اللجنة .
4- آلية إعداد محاضر الاجتماعات ، ودورية عرض التقارير على مجلس الإدارة بشأن نتائج أعمالها .
5- آلية رقابة المجلس على عمل اللجنة .
6- بدلات حضور وانتقال أعضاء اللجنة .$b22_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-10-22', 'active' FROM ins22_0;

WITH ins23_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 23, 0, $h23$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل الرابع - اللجان المشكلة من مجلس إدارة الشركة$h23$, $t23_0$المادة 23 - اللجان المشكلة من مجلس إدارة الشركة وتشكيلها ودورية انعقادها$t23_0$, $b23_0$تشكل اللجان المشار إليها بالمادة السابقة بقرار من مجلس إدارة الشركة ، وتشكل اللجان الآتية : لجنة الترشيحات والمكافآت ، ولجنة المراجعة الداخلية ، ولجنة المخاطر ، ولجنة الاستثمار ، ولجنة الحوكمة ، ولجنة حماية حقوق حملة الوثائق ، من عدد فردى من الأعضاء لا يقل عن ثلاثة أعضاء من بين أعضاء مجلس الإدارة غير التنفيذيين والمستقلين ، مع جواز أن يضم تشكيل لجنة الاستثمار العضو المنتدب/ الرئيس التنفيذى للشركة .
وتشكل اللجان الآتية : لجنة تكنولوجيا المعلومات والتحول الرقمى ، ولجنة تطوير المنتجات التأمينية ، ولجنة إدارة الأصول والالتزامات ، ولجنة الممارسات البيئية والمجتمعية والحوكمة المتعلقة بالاستدامة والحوكمة المناخية ، من عدد فردى من الأعضاء لا يقل عن ثلاثة أعضاء من بين أعضاء مجلس الإدارة أو الإدارة التنفيذية العليا بالشركة .
ويجوز أن تضم عضوية اللجان المشكلة من مجلس الإدارة أعضاء من ذوى الخبرة من خارج الشركة ، شريطة تمتعهم بالنزاهة والأمانة والكفاءة ، وتوافر المعرفة والخبرة اللازمة لأداء المهام المسندة إليهم ، على أن تتناسب خبراتهم السابقة مع طبيعة عمل اللجنة المنضمين إليها ، وتجنب حالات تعارض المصالح ، والالتزام بأحكام التشريعات السارية .
وتجتمع اللجان بصورة دورية وعلى الأقل مرة واحدة كل ثلاثة أشهر ، ويكون الاجتماع صحيحًا بحضور نصف عدد أعضائها أو الحد الأدنى من تشكيلها ، وتصدر توصياتها بأغلبية أصوات الأعضاء الحاضرين وفى حالة التساوى يرجح الجانب الذى منه رئيس اللجنة .
ويجوز للجان الاستعانة بمن تراه ضروريًا لمعاونتها فى أداء مهامها دون أن يكون له صوت معدود عند التصويت شريطة الحصول على موافقة مسبقة من مجلس الإدارة ، ومراعاة تجنب حالات تعارض المصالح .
وتلتزم اللجان بموافاة مجلس إدارة الشركة بصورة دورية من نتائج أعمالها وتوصياتها ومحاضر اجتماعاتها ، ويتولى المجلس اتخاذ القرارات المناسبة بشأنها خلال مدة لا تجاوز ثلاثين يومًا من تاريخ عرضها عليه ويلتزم رئيس مجلس الإدارة بموافاة الهيئة بمحاضر تلك اللجان ، والقرارات التى اتخذها المجلس بشأن التوصيات والملاحظات خلال مدة لا تتجاوز عشرة أيام عمل من تاريخ صدورها .
ويتعين على المجلس متابعة أداء اللجان وعلى الأقل مرة سنويًا للتحقق من تنفيذ مهامها وفق ميثاقها التنظيمى .$b23_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-10-22', 'active' FROM ins23_0;

WITH ins24_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 24, 0, $h24$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل الرابع - اللجان المشكلة من مجلس إدارة الشركة$h24$, $t24_0$المادة 24 - لجنة الترشيحات والمكافآت$t24_0$, $b24_0$تختص لجنة الترشيحات والمكافآت بحد أدنى بما يلى :
1- تحديد مسئوليات أعضاء مجلس الإدارة التنفيذيين وغير التنفيذيين والمستقلين وإعداد الوصف الوظيفى للقائمين على الإدارة التنفيذية العليا .
2- إجراء مراجعة دورية ومستمرة لاحتياجات الشركة من المهارات والخبرات المناسبة لعضوية مجلس الإدارة ، والإدارة التنفيذية العليا ، وإعداد بيان بالمؤهلات المطلوبة .
3- رفع التوصيات إلى مجلس الإدارة بترشيح التخصصات أو الأشخاص ممن تراه اللجنة مناسبًا لعضوية مجلس الإدارة من المستقلين أو عضوية لجانه ، وفقًا للمتطلبات النظامية والسياسات والمعايير المعتمدة ، وكذلك التوصية بتعيين أو إعفاء أى من الإدارة التنفيذية العليا .
4- تقييم هيكل تشكيل مجلس الإدارة ولجانه ، وتحديد جوانب الضعف بصفة دورية ، واقتراح الإجراءات اللازمة لمعالجتها .
5- التأكد من وجود آلية فعالة لتقييم أداء مجلس الإدارة ولجانه ، وتطبيقها بشكل فعال مرة واحدة على الأقل سنويًا .
6- الإشراف على تنفيذ البرنامج التعريفى والتدريب الدورى لأعضاء مجلس الإدارة .
7- إعداد سياسات واضحة بشأن المكافآت والبدلات والاستحقاقات الخاصة بأعضاء مجلس الإدارة وأعضاء اللجان والإدارة التنفيذية العليا ، بما فى ذلك العضو المنتدب/ الرئيس التنفيذى ، ويجب الاستعانة بمعايير تربط تلك السياسات بمعايير أداء محددة ، على أن يتم مراجعة تلك السياسات بصورة سنوية بناءً على دراسات واستقصاءات مستقلة ودون تدخل من الإدارة التنفيذية بالشركة .
8- مراجعة خطة التعاقب الوظيفى ، والتأكد من كفاءة تطبيقها .
9- وضع سياسة ترشيح واختيار الإدارة التنفيذية العليا بالشركة ، بالإضافة إلى وضع سياسة لضمان استمرارية ملاءمة وتناسب الأشخاص المرشحين أو شاغلى تلك الوظائف بما يتوافق مع التشريعات الصادرة فى هذا الشأن ، على أن يتم تحديث هذه السياسات بشكل دورى واعتمادها من مجلس الإدارة .
ويجوز للشركة فصل اختصاصات تلك اللجنة وتشكيل لجنتين مستقلتين أحدهما للترشيحات والأخرى للمكافآت على أن تحدد اختصاصات كل منهما بوضوح .$b24_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-10-22', 'active' FROM ins24_0;

WITH ins25_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 25, 0, $h25$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل الرابع - اللجان المشكلة من مجلس إدارة الشركة$h25$, $t25_0$المادة 25 - لجنة المراجعة الداخلية$t25_0$, $b25_0$يجب أن يكون رئيس لجنة المراجعة الداخلية من أعضاء مجلس الإدارة المستقلين ، وتختص لجنة المراجعة بحد أدنى بما يلى :
1- نظم الرقابة الداخلية :
(أ) دراسة نظام الرقابة الداخلية المطبق بالشركة ، والتحقق من كفاءة وفعالية أساليب الرقابة الداخلية ، وإجراء تقييم دورى للإجراءات المطبقة ، مع اقتراح التعديلات اللازمة على ذلك .
(ب) مراجعة البيانات الدورية التى تقدم إلى الهيئة ، والتأكد من صحة أسس إعدادها ، وتوقيت عرضها ، وإبداء الرأى الفنى والتوصيات بشأنها .
(ج) وضع آلية تتيح للعاملين بالشركة وكذلك المتعاملين الخارجيين تقديم البلاغات عن أية مخالفات أو تجاوزات بشكل سرى ، على أن تتولى إدارة الالتزام إعداد تقارير دورية للجنة المراجعة الداخلية تتضمن ملخصًا لتلك البلاغات والإجراءات المتخذة بشأنها .
(د) إجراء مراجعة دورية لتقارير إدارة شكاوى العملاء بالشركة ، والتأكد من قيامها بمهامها وفق القرارات الصادرة عن الهيئة فى هذا الشأن .
(ه) إجراء مراجعة دورية لتقارير وإحصائيات قياس مستوى رضاء العملاء عن الخدمات المقدمة لهم ، مع إبداء الرأى والتوصيات اللازمة لتحسين جودة تلك الخدمات ، وذلك بمراعاة الضوابط الصادرة عن الهيئة بشأن قياس رضاء العملاء لدى شركات التأمين .
(و) فحص النظم الموضوعة للتأكد من كفاءتها وفعاليتها فى مجال مكافحة غسل الأموال وتمويل الإرهاب واقتراح ما يلزم من إجراءات وقائية ، ومتابعة تطويرها بشكل مستمر .
2- التقارير :
(أ) التحقق من كفاية المخصصات والاحتياطات بالشركة لتغطية التزاماتها .
(ب) دراسة القوائم المالية وقوائم التدفقات النقدية الدورية والسنوية للشركة ، والتحقق من التزام هذه القوائم بالمعايير المحاسبية الخاضع لها الشركة ، وإبداء رأيها وتوصياتها بخصوصها .
(ج) دراسة النظم والسياسات المحاسبية المطبقة بالشركة ، ومتابعة التغيرات التى تطرأ نتيجة تطبيق معايير أو قواعد محاسبية جديدة ، مع إبداء الرأى الفنى والتوصيات اللازمة حيالها .
(د) الاطلاع على تقرير مسئول المراجعة الداخلية بشأن نتائج أعمال مسئول مكافحة غسل الأموال وتمويل الإرهاب وذلك قبل العرض على مجلس الإدارة ، واقتراح ما يلزم من إجراءات لتجنب أى أمور من شأنها التأثير على متطلبات مكافحة غسل الأموال وتمويل الإرهاب أو الاضرار بسمعة الشركة أو تعرضها لتدابير أو عقوبات ناتجة عن عدم الالتزام .
3- مراقب الحسابات :
(أ) التوصية لمجلس الإدارة بتعيين مراقب حسابات أو أكثر للشركة ، على أن تتوافر فيه الكفاءة والاستقلالية والخبرة المتطلبة لذلك ، وتحديد أتعابه ويكون اعتماد قرار تعيينه من اختصاص الجمعية العامة للشركة .
(ب) دراسة ملاحظات وتوصيات مراقب الحسابات على القوائم المالية ، ومتابعة ما تم بشأنها .
(ج) النظر فى الموافقة على تكليف مراقب الحسابات بمهام إضافية بخلاف مراجعة حسابات الشركة ، مع التوصية بالمقابل المالى له بما يتناسب مع أتعابه السنوية تمهيدًا للعرض على الجمعية العامة للشركة للاعتماد .
4- المراجعة الداخلية :
(أ) اعتماد تعيين رئيس إدارة المراجعة الداخلية بالشركة ، وتحديد أتعابه ، وتقييم أدائه ، والنظر فى استبداله عند الاقتضاء .
(ب) مناقشة واعتماد الخطة السنوية لإدارة المراجعة الداخلية ، ومتابعة تنفيذها والتأكد من شمولها لكافة إدارات وأنشطة الشركة .
(ج) الاطلاع على تقارير المراجعة الداخلية ، وتحديد أوجه وأسباب القصور فى الشركة ومتابعة تنفيذ الإجراءات التصحيحية لها .
5- الخبرة الاكتوارية :
(أ) التوصية لمجلس الإدارة بتعيين خبير اكتوارى خارجى أو أكثر للشركة أو استبداله مع مراعاة مؤهلاته وكفاءته واستقلاليته وتحديد أتعابه وذلك وفقًا لقرارات الهيئة الصادرة فى هذا الشأن .
(ب) دراسة ملاحظات الخبير الاكتوارى الخارجى بشأن المخصصات الفنية وسياسات تسعير المنتجات ، وكافة أعمال الشركة ، ومتابعة ما تم بشأنها .
6- ضمان الالتزام :
(أ) التأكد من التزام الشركة بكافة القوانين والقرارات الصادرة عن الهيئة ، ولوائح العمل الداخلية بناءً على التقارير الواردة من إدارة الالتزام أو غيرها من الإدارات المعنية الأخرى .
(ب) التأكد من استقلالية كل من المراجعين الداخليين ، ومراقب الحسابات ، والخبير الاكتوارى الخارجى .
