WITH ins35_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 35, 0, $h35$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل الخامس - الإدارات الرقابية والحوكمة$h35$, $t35_0$المادة 35 - أحكام عامة$t35_0$, $b35_0$تلتزم الشركات المخاطبة بأحكام هذا القرار بأن يكون لديها آليات ملائمة للرقابة الداخلية والالتزام ، وأن يساعد تشكيل هيكلها الداخلى على اتخاذ القرارات السليمة والإجراءات الاحترازية ، وتعزيز كفاءة ووضوح العمليات داخل الشركة .
وتشمل أهداف نظام الرقابة الداخلية بالشركة بحد أدنى ما يلى :
1- تحقيق الفصل التام بين مسئوليات وسلطات كافة العاملين بالشركة .
2- ضمان دقة وجودة المعلومات بما يسمح بتوفير معلومات صحيحة ودقيقة للعاملين بالشركة والأطراف ذات العلاقة من خارجها على حد سواء .
3- حماية الأصول المادية للشركة من الأخطار المحتملة وتوثيقها بسجلات الشركة .
4- رفع الكفاءة الإنتاجية للشركة وتحقيق أهدافها بأقل تكلفة وبذات مستوى الجودة .
5- ضمان دقة تنفيذ التعليمات .
6- ضمان تطبيق قواعد وتعليمات حوكمة الشركات بدقة .
وفى جميع الأحوال ، يتعين منح الإدارة التنفيذية العليا السلطات والصلاحيات اللازمة لمباشرة عملهم داخل الشركة ، وضمان استقلاليتهم .
ويجب أن يقوم المسئولون الرئيسيون عن الإدارات الآتية : المخاطر ، والالتزام ، والمراجعة الداخلية ، والحوكمة ، ومكافحة غسل الأموال وتمويل الإرهاب بتقييم مدى ملائمة السياسات والعمليات والإجراءات بالإدارات المسئولين عنها بالشركة ، وتحديد أوجه وأسباب القصور فيها ، واقتراح إجراءات تصحيحها ، ويجب أن يتاح لهم حرية الاتصال المباشر مع جميع الأشخاص المعنيين وكذا الاطلاع على جميع البيانات والتقارير والوثائق ذات الصلة . ويجب أن تبين لائحة الحوكمة الخاصة بالشركة مدى ملاءمة ومناسبة الأشخاص المنوط بهم القيام بتلك الوظائف وكذا دور ومسئوليات كل وظيفة فى ضوء التشريعات المنظمة لذلك .$b35_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-10-22', 'active' FROM ins35_0;

WITH ins36_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 36, 0, $h36$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل الخامس - الإدارات الرقابية والحوكمة$h36$, $t36_0$المادة 36 - إدارة المخاطر$t36_0$, $b36_0$تلتزم الشركات المخاطبة بأحكام هذا القرار بإنشاء إدارة مستقلة لإدارة المخاطر ، ويقوم مجلس الإدارة باعتماد استراتيجية واضحة لتحديد المخاطر التى قد تواجه الشركة وآليات التعامل معها ، مع تحديد مستوى المخاطر المقبول لديها .
وتختص إدارة المخاطر بحد أدنى بما يلى :
1- تحليل المخاطر التى قد تتعرض لها الشركة بدقة وفى وقت مناسب ومبكر .
2- اقتراح السياسات والإجراءات لإدارة المخاطر ، لتحديد وتقييم ومراقبة وقياس وضبط المخاطر والحد منها وعرضها على لجنة المخاطر تمهيدًا لاعتمادها من مجلس إدارة الشركة ، والقيام بتطبيقها بعد اعتمادها .
3- قياس مدى استمرار ملائمة وفاعلية السياسات المتبعة فيما يخص قياس ومتابعة ومراقبة المخاطر ، واقتراح أى تعديلات مطلوبة بشأنها طبقًا لتطورات وتغيرات السوق والبيئة المحيطة بالشركة داخليًا وخارجيًا ووضع خطة للطوارئ .
4- التأكد من توافر نظم معلومات واتصال فعالة فيما يتعلق بعملية متابعة ومراقبة المخاطر ، بحيث تتيح للإدارة العليا ولجنة المخاطر تلقى تقارير دورية ربع سنوية على الاقل من إدارة المخاطر توضح مدى التزام الشركة بحدود المخاطر المحددة ، وأسباب أى تجاوزات وخطة المعالجة .
5- تقديم تقارير دقيقة ومعبرة ، تمكن المعنيين من اتخاذ القرارات المناسبة بشأنها .
ويجب على الشركة الالتزام بما يلى :
1- أن يتولى إدارة المخاطر مسئول رئيسى متفرغ يتبع فنيًا لجنة المخاطر ، ويتم تعيينه واستبداله وتحديد معاملته المالية بناءً على توصية لجنة المخاطر ، ولا يجوز تعديل معاملته المالية أو أى مزايا يحصل عليها دون الرجوع للجنة المخاطر .
2- أن يتمتع المسئول الرئيسى عن إدارة المخاطر بالاستقلال التام عن باقى الوظائف بالشركة .
3- أن يتناسب عدد العاملين فى إدارة المخاطر ومستوى معرفتهم وخبراتهم مع حجم وطبيعة أعمال الشركة .
وترفع إدارة المخاطر تقاريرها إلى لجنة المخاطر ، ويجب تمكين المسئول الرئيسى عن إدارة المخاطر من التواصل مباشرة مع لجنة المخاطر دون عوائق .$b36_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-10-22', 'active' FROM ins36_0;

WITH ins37_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 37, 0, $h37$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل الخامس - الإدارات الرقابية والحوكمة$h37$, $t37_0$المادة 37 - إدارة الالتزام$t37_0$, $b37_0$تلتزم الشركات المخاطبة بأحكام هذا القرار بإنشاء إدارة مستقلة للالتزام ، وتعد مسئولية الالتزام بالتشريعات السارية هى مسئولية كافة العاملين بالشركة ، ولا تقتصر على إدارة الالتزام .
وتكون الإدارة التنفيذية العليا بالشركة مسئولة عن وضع السياسات المتعلقة بوظيفة إدارة الالتزام ، ويقوم مجلس الإدارة باعتماد تلك السياسات على أن يتم التأكد من إحاطة كافة العاملين بها .
وترفع إدارة الالتزام تقاريرها إلى لجنة المراجعة الداخلية ، ويتولى إدارة الالتزام مسئول رئيسى يتبع فنيًا لجنة المراجعة الداخلية ، ويتم تعيينه واستبداله وتحديد معاملته المالية بناءً على توصية لجنة المراجعة الداخلية ، ولا يجوز تعديل معاملته المالية أو أى مزايا يحصل عليها دون الرجوع للجنة المراجعة الداخلية .
وتختص إدارة الالتزام بحد أدنى يما يلى :
1- تحديد وتقييم وإعداد التقارير بشأن مخاطر عدم الالتزام بالتشريعات السارية تجنبًا للإضرار بسمعة الشركة أو تعرضها لتدابير أو مخالفات أو عقوبات ناتجة عن عدم الالتزام .
2- المتابعة الدورية والتأكد من التزام كافة العاملين بالتشريعات السارية واللوائح والسياسات والمواثيق الداخلية بالشركة ، بما فى ذلك ميثاق شرف العاملين .
3- التأكد من وجود خطة لتحديث بيانات العملاء ومراجعتها .
4- التأكد من عدم وجود ممارسات غير مشروعة أو غير أخلاقية بالشركة ، وتلقى البلاغات والتحقيق فيها بشكل موضوعى وسرى وعرضها على لجنة المراجعة الداخلية ومتابعة ما تم بشأنها ، وضمان حماية المبلغين عن تلك الممارسات .
5- التأكد من تلقى أعضاء مجلس إدارة الشركة والعاملين بها لدورات تدريبية مناسبة لطبيعة أعمالهم بالشركة ، وكذا التأكد من إلمامهم بالتشريعات السارية بما فى ذلك قواعد الحوكمة .$b37_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
