WITH ins43_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 43, 0, $h43$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل السادس - الإفصاح والشفافية$h43$, $t43_0$المادة 43 - التقرير السنوى عن نشاط الشركة$t43_0$, $b43_0$يلتزم مجالس إدارة الشركات المخاطبة بأحكام هذا القرار بإعداد تقرير سنوى عن نشاط الشركة يعرض على الجمعية العامة للشركة ، ويتم موافاة الهيئة به وفقًا للضوابط السارية فى هذا الشأن ، ويجب أن يتضمن بحد أدنى ما يلى :
1- طبيعة نشاط الشركة ، وأهدافها ، ورؤيتها ، واستراتيجيتها المستقبلية .
2- استعراض استراتيجية الشركة وبيان أى تعديلات جوهرية طرأت عليها خلال العام .
3- بيان بالإنجازات الرئيسية التى حققتها الشركة خلال العام .
4- تحليل لبيئة عمل الشركة ، والسوق الذى تعمل به .
5- القرارات الجوهرية المتخذة وأثرها على أداء ووضع الشركة .
6- تحليل لأهم المخاطر التى تواجه الشركة حاليًا أو مستقبلاً ، والإجراءات المتخذة فى هذا الشأن .
7- تقرير عن وضع الملاءة المالية للشركة ومستوى المخاطر التى قد تتعرض لها وكيفية إدارة هذه المخاطر .
8- تحليل المركز المالى للشركة .
9- القوائم المالية والإفصاحات المتممة لها ، وتقرير مراقب الحسابات بشأنها .
10- تقرير عن نتائج المراجعة السنوية لكفاءة وفعالية نظام الرقابة الداخلية للشركة .
11- هيكل ملكية الشركة وبيان نسبة تملك كل من مساهميها والتغيرات التى تمت على هيكل الملكية خلال العام المالى المنقضى .
12- تشكيل مجلس الإدارة ، وأسماء أعضاء المجلس وتصنيفهم ، وصفة كل عضو بالمجلس ، وتاريخ بداية ونهاية الدورة الحالية ، وعدد الاجتماعات المعقودة خلال الفترة وتواريخها ، وأسماء حضور كل اجتماع ، وقيمة البدلات والمكافآت التى صرفت لأعضاء مجلس الإدارة .
13- تشكيل كل لجنة من اللجان المشكلة من مجلس إدارة الشركة وبيان صفة أعضائها ، وعدد اجتماعات كل لجنة ، وقيمة البدلات والمكافآت التى صرفت لأعضاء تلك اللجان .
14- قائمة بأسماء ومناصب ومؤهلات وخبرات كل عضو من أعضاء الإدارة التنفيذية العليا بالشركة .
15- بيان سياسات الإثابة والتحفيز المعتمدة للعاملين بالشركة .
16- بيان التعاملات التى تمت بين الشركة والشركة الأم وأى من شركاتها التابعة أو الشقيقة ، والأطراف ذات العلاقة بما فى ذلك كبار المساهمين وأعضاء مجلس الإدارة والإدارة التنفيذية العليا خلال العام المالى المنقضى .
17- بيان بعقود المعاوضة التى أبرمت خلال العام المنقضى ، والعقود المزمع إبرامها خلال العام القادم .
18- مدى وجود حالات لتعارض المصالح أو شبهة تعارض مصالح والإجراءات التى اتخذتها الشركة بشأنها .
19- بيان التدابير أو المخالفات أو الدعاوى القضائية التى اتخذت ضد الشركة أو ضد أى من أعضاء مجلس إدارتها أو الإدارة التنفيذية العليا والمتعلقة بمهامهم الوظيفية .$b43_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
