SELECT id, 1, body, '2025-10-22', 'active' FROM ins43_0;

WITH ins44_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 44, 0, $h44$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل السادس - الإفصاح والشفافية$h44$, $t44_0$المادة 44 - تقرير الممارسات البيئة والمجتمعية والحوكمة المتعلقة بالاستدامة والحوكمة المناخية$t44_0$, $b44_0$تلتزم الشركات المخاطبة بأحكام هذا القرار بإعداد تقرير سنوى عن الممارسات البيئة والمجتمعية والحوكمة المتعلقة بالاستدامة والحوكمة المناخية وفقًا للقرارات الصادرة عن الهيئة فى هذا الشأن ، وعرضه على الجمعية العامة .$b44_0$
