WITH ins45_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 45, 0, $h45$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل السادس - الإفصاح والشفافية$h45$, $t45_0$المادة 45 - التعهيد$t45_0$, $b45_0$فى حال قيام أى من الشركات المخاطبة بأحكام هذا القرار بتعهيد أيًا من خدماتها للغير فتلتزم بإبرام كافة اتفاقيات التعهيد وفقًا لشروط وسياسة التعهيد المعتمدة من مجلس إدارتها ، والتأكد من توافقها مع أحكام التشريعات السارية والسياسات الداخلية المعتمدة بالشركة ، مع ضرورة إخطار مجلس الإدارة ولجنة المخاطر بشكل دورى بتلك الاتفاقيات .
ويجب أن تتضمن اتفاقيات التعهيد بحد أدنى ما يلى :
إجراءات ضمان أمن وحماية البيانات التى تم مشاركتها .
النص صراحة على احتفاظ الشركة دائمًا بحقوق ملكية تلك البيانات .
الإجراءات المتبعة لإنهاء مشاركة البيانات والبرمجيات ذات الصلة عند انتهاء مدة التعاقد ، وبما لا يخل باحتفاظ الشركة بحق ملكية تلك البيانات .
كما تلتزم الشركة بتقييم أداء جهات التعهيد مرة واحدة على الأقل سنويًا أو كلما دعت الحاجة إلى ذلك ، على أن يتم إخطار الهيئة ومجلس إدارة الشركة بنتائج هذا التقييم .$b45_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-10-22', 'active' FROM ins45_0;

WITH ins46_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 46, 0, $h46$قواعد حوكمة شركات التأمين وإعادة التأمين - الفصل السادس - الإفصاح والشفافية$h46$, $t46_0$المادة 46 - سياسة منع تعارض المصالح$t46_0$, $b46_0$تلتزم الشركات المخاطبة بأحكام هذا القرار بإعداد سياسة تهدف إلى منع تعارض المصالح لأعضاء مجلس الإدارة والعاملين بها ، وذلك تعزيزًا لمبادئ النزاهة والشفافية وتطبيقًا لمبدأ المساءلة والمحاسبة عن أى أعمال أو ممارسات قد تؤدى إلى تعارض المصالح .
ويجب أن تتضمن سياسة التناسب والملاءمة الخاصة بشغل الوظائف التنفيذية بالشركة على قواعد وضوابط لتجنب حالات تعارض المصالح ، بما فى ذلك وضع آليات الإفصاح عن تلك الحالات أو الشبهة بها والإجراءات الواجب إتباعها لمواجهتها .
كما يتعين على مجلس إدارة الشركة وضع الآليات الكافية لتجنب حالات تعارض المصالح المحتملة ووضع الإجراءات والضوابط اللازمة للتعامل معها ومعالجتها بطريقة صحيحة ، على أن تتضمن بحد أدنى ما يلى :
أولاً - بالنسبة لأعضاء مجلس الإدارة
1- لا يجوز للعضو المنتدب/ الرئيس التنفيذى الجمع بين منصبه وأى منصب تنفيذى آخر داخل الشركة ، كما لا يجوز له شغل عضوية مجلس إدارة أو شغل أى وظيفة تنفيذية فى أى من الشركات والجهات التى تزاول المهن والأنشطة المرتبطة بالتأمين ، وذلك على النحو الوارد بقانون التأمين الموحد .
2- لا يجوز للعضو المنتدب/ الرئيس التنفيذى المشاركة فى تأسيس أو المساهمة أو إدارة أى من الشركات والجهات التى تزاول المهن والأنشطة المرتبطة بالتأمين ، وذلك على النحو الوارد بقانون التأمين الموحد .
3- لا يجوز للعضو المنتدب/ الرئيس التنفيذى قبول أو التدخل مع أقاربهم حتى الدرجة الثانية فى أى عمليات وساطة تأمينية ، أو التوسط أو تقديم أى من الخدمات التأمينية المتعلقة بالمهن والأنشطة المرتبطة بالتأمين داخل جمهورية مصر العربية وذلك على النحو الوارد بقانون التأمين الموحد ، ووفقًا للتشريعات المنظمة لذلك .
4- لا يجوز لعضو مجلس الإدارة مزاولة نشاط الوساطة فى التأمين أو إعادة التأمين لحسابه الخاص .
5- لا يجوز أن يكون لعضو مجلس الإدارة مصلحة شخصية – سواء مباشرة أو غير مباشرة – فى الأعمال أو العقود التى تبرم لحساب الشركة إلا بعد الحصول على موافقة مسبقة من الجمعية العامة للشركة وتجدد سنويًا ، كما يتعين الحصول على موافقة الجمعية العامة على كل عقد معاوضة على حدة قبل إبرامه ، وذلك فيما عدا الأعمال والعقود التى تتم بطريق المناقصات أو الممارسات أو المزايدات أو تلقى عروض أسعار عامة وما فى حكمها إذا كان عضو مجلس الإدارة هو صاحب العرض الأفضل ، ويجب على عضو مجلس الإدارة حال وجود مصلحة له فى أى من تلك الأعمال أو العقود أن يخطر مجلس الإدارة بذلك على الفور ، ويتم إثبات هذا الإخطار فى محضر اجتماع المجلس ، ولا يجوز لعضو مجلس الإدارة صاحب المصلحة الاشتراك فى المداولات أو التصويت على القرار الصادر فى هذا الشأن .
6- لا يجوز لعضو مجلس الإدارة الاشتراك فى أى عمل من شأنه منافسة الشركة أو أحد فروع النشاط الذى تزاوله ، إلا بعد الحصول على موافقة مسبقة من الجمعية العامة للشركة تجدد سنويًا .
7- يجب على رئيس مجلس الإدارة أن يفصح للجمعية العامة عن تفاصيل عقود التأمين التى يكون لأحد أعضاء مجلس الإدارة مصلحة فيها ، على أن يتضمن الإفصاح نوعية هذه العقود ، وقيمتها ، وأية خسائر مترتبة عليها .
8- يتعين على عضو مجلس الإدارة أن يفصح كتابة لمجلس إدارة الشركة وإخطار الهيئة عند قيامه أو أى من أقاربه حتى الدرجة الثانية بتأسيس أو ملكية أو إدارة أى من المنشآت التى تزاول نشاط التأمين وإعادة التأمين ، وكذا أى من شركات المهن والأنشطة المرتبطة بالتأمين ، وفى هذه الحالة يتعين عليه الامتناع عن الترويج أو الحث على التعامل مع الشركة التى تربطه علاقة بها ، وكذا الامتناع عن التصويت على أى من القرارات المرتبطة بها .
9- لا يجوز لعضو مجلس الإدارة تقديم أية استشارات أو خدمات مدفوعة الأجر سواء للشركة أو شركاتها التابعة أو الأطراف المرتبطة بها ، مالم تكن هذه الخدمات مرتبطة بعقود معاوضة وافقت عليها مسبقًا الجمعية العامة للشركة .
ثانياً - العاملون بالشركة
1- لا يجوز للعاملين بالشركة الجمع بين وظيفتهم وعضوية مجلس إدارة أو أى وظيفة تنفيذية أخرى بأى من شركات تأمين أو إعادة التأمين ، كما لا يجوز لهم الاشتراك فى أى عمل من شأنه منافسة الشركة .
2- لا يجوز للعاملين بالشركة تأسيس أو شغل عضوية مجلس إدارة أو شغل أى وظيفة تنفيذية أخرى لدى أى من شركات المهن والأنشطة المرتبطة بالتأمين .
3- لا يجوز للعاملين بالشركة قبول أو التدخل مع أقاربهم حتى الدرجة الرابعة فى أى عمليات وساطة تأمينية ، أو التوسط أو تقديم أى من الخدمات التأمينية المتعلقة بالمهن والأنشطة المرتبطة بالتأمين .
4- لا يجوز للعاملين بالشركة أن يكون لهم مصلحة شخصية – سواء مباشرة أو غير مباشرة – فى الأعمال أو العقود التى تبرم لحساب الشركة ، ويتعين عليهم إخطار مجلس الإدارة بذلك على الفور ، وعلى المجلس اتخاذ ما يلزم من إجراءات لمنع أى تعارض فى المصالح .
وتلتزم الشركات المخاطبة بأحكام هذا القرار بإخطار الهيئة خلال شهر من سريانه بأى من الحالات القائمة الآتية :
1- توافر أى من الحالات المشار إليها بهذه المادة بشأن أعضاء مجلس الإدارة أو العاملين بالشركة .
2- قيام أى من أعضاء مجلس الإدارة أو الإدارة التنفيذية العليا أو أقاربهم حتى الدرجة الثانية بتملك أو شغل عضوية مجلس إدارة أو تولى أى من الوظائف بشركات التأمين أو إعادة التأمين الأخرى ، أو شركات المهن والأنشطة المرتبطة بالتأمين .
3- أية علاقة قرابة أو مصاهرة بين أعضاء مجلس الإدارة أو الإدارة التنفيذية العليا بالشركة وبين أى من أعضاء مجلس إدارة أو العاملين بأى من شركات المهن والأنشطة المرتبطة بالتأمين أو مساهمى تلك الشركات .$b46_0$
  FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-10-22', 'active' FROM ins46_0;

DO $verify162$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 200 AND law_year = 2025 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[162] القرار 200/2025 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 50 THEN RAISE EXCEPTION '[162] عدد المواد % بدل 50', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2025-10-22';
  IF v_v <> 50 THEN RAISE EXCEPTION '[162] عدد النسخ % بدل 50', v_v; END IF;
