  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 45 AND article_suffix_order = 0 AND body LIKE 'فى حال قيام أى من الشركات المخاطبة بأحكام هذا%' AND body LIKE '%رة الشركة بنتائج هذا التقييم .' AND body LIKE '%مرة واحدة على الأقل سنويًا%') THEN RAISE EXCEPTION '[162] المادة 45 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 46 AND article_suffix_order = 0 AND body LIKE 'تلتزم الشركات المخاطبة بأحكام هذا القرار بإعد%' AND body LIKE '%لتأمين أو مساهمى تلك الشركات .' AND body LIKE '%الدرجة الرابعة%' AND body LIKE '%الدرجة الثانية%' AND body LIKE '%خلال شهر من سريانه%' AND body LIKE '%أولاً - بالنسبة لأعضاء مجلس الإدارة%' AND body LIKE '%ثانياً - العاملون بالشركة%') THEN RAISE EXCEPTION '[162] المادة 46 غير سليم'; END IF;
  IF v_len <> 62809 THEN RAISE EXCEPTION '[162] إجمالى طول المواد % بدل 62809', v_len; END IF;
  RAISE NOTICE '[162] القرار 200/2025: 50 مواد و50 نسخ، إجمالى % حرف', v_len;
END
$verify162$;

COMMIT;
